import test from 'node:test';
import assert from 'node:assert/strict';
import {evaluateMonitorDeployment as check} from './payne-monitor-deployment-eligibility.mjs';
function sample(){return {source:{baseline:'6b2174211bd7ba4f52c01d5037f9bef46e424f14',promotion:'7abf271cbcbb5816459559e9deefb8987e8c31d0',cockpitBlob:'810f4d509413e678ab3db638ba5f6dfd8cff4364',onlyChangedFile:'market-edge-lab/real/payne-kalshi-real/src/cockpit-html.js'},control:{realControlSchema:'PAYNE_REAL_CONTROL_V2_PAPER_BRAIN',armed:false,openPositions:0,activeThreshold:.65,attemptTarget:10,maxEntryDebitUsd:1},series:{schema:'PAYNE_REAL_SERIES_V1',owner:'PAYNE_KALSHI_REAL',seriesId:'example',configFrozen:true,threshold:.8,attemptTarget:5,maxEntryDebitUsd:1,unresolvedEntry:false,position:null,currentAttempt:null,positions:[],fireLatch:{state:'NONE'}},evidence:{authority:'AUTHENTICATED_READONLY_VERIFIER',source:'AUTHENTICATED_READ_ONLY',seriesId:'example',observedAt:'2026-10-20T12:00:00Z',providerOrdersComplete:true,providerPositionsComplete:true,coordinatorClaimsComplete:true,reconciliationComplete:true,providerOpenOrders:0,providerOpenPositions:0,coordinatorActiveClaims:0,unknownProviderObligations:0,providerPostUnknown:false,unresolvedOwnership:false},now:Date.parse('2026-10-20T12:00:30Z')}}
test('historical mismatch does not block verified safe display deployment',()=>{for(const t of [.5,.65,.8,.95])for(const n of [1,5,10])for(const stake of [.5,1,2]){let x=sample();x.control.activeThreshold=t;x.control.attemptTarget=n;x.control.maxEntryDebitUsd=stake;assert.equal(check(x).allowed,true)}});
test('active or unknown exposure always blocks',()=>{for(const [k,v] of [['providerOpenOrders',1],['providerOpenPositions',1],['coordinatorActiveClaims',1],['unknownProviderObligations',null],['providerPostUnknown',true],['unresolvedOwnership',true]]){let x=sample();x.evidence[k]=v;assert.equal(check(x).allowed,false,k)}});
test('incomplete and stale provider coverage blocks',()=>{for(const k of ['providerOrdersComplete','providerPositionsComplete','coordinatorClaimsComplete','reconciliationComplete']){let x=sample();x.evidence[k]=false;assert.equal(check(x).allowed,false,k)}let x=sample();x.evidence.observedAt='2026-10-20T11:55:00Z';assert.equal(check(x).allowed,false)});
test('unresolved ownership, execution and ARM block',()=>{for(const edit of [x=>x.series.unresolvedEntry=true,x=>x.series.currentAttempt={},x=>x.series.fireLatch.state='LATCHED',x=>x.control.armed=true]){let x=sample();edit(x);assert.equal(check(x).allowed,false)}});
test('missing evidence or wrong source pin blocks',()=>{let x=sample();delete x.evidence;assert.equal(check(x).allowed,false);x=sample();x.source.cockpitBlob='wrong';assert.equal(check(x).allowed,false)});
